keys=[int.from_bytes((s[:6]+b'\0'*6)[:6],'little')|len(s)<<48 for s in names]
def build(hs,B=128,S=512,shift=7):
 groups=[[] for _ in range(B)]
 for i,h in enumerate(hs):groups[h&(B-1)].append((i,h))
 g=[0]*B;used=[False]*S;slots=[None]*S
 for b,a in sorted(enumerate(groups),key=lambda z:-len(z[1])):
  if len(a)<=1: continue
  bases=[(h>>shift)&(S-1) for i,h in a]
  for d in range(S):
   ts=[(z+d)&(S-1) for z in bases]
   if len(set(ts))==len(ts) and not any(used[t] for t in ts):
    g[b]=d
    for t,(i,h) in zip(ts,a):used[t]=1;slots[t]=i
    break
  else:return None
 free=iter(i for i,u in enumerate(used) if not u)
 for b,a in enumerate(groups):
  if len(a)==1:
   i,h=a[0];q=next(free);g[b]=(q-((h>>shift)&(S-1)))&(S-1);slots[q]=i
 for i,h in enumerate(hs):
  if slots[((h>>shift)+g[h&(B-1)])&(S-1)]!=i:return None
 return max(map(len,groups)),sum(len(x)>1 for x in groups)
def show(name,fn):
 hs=[fn(k)&0xffffffff for k in keys]
 u=len(set(hs));
 for B,S,shift in [(128,512,7),(256,512,8),(128,1024,7),(64,512,6),(256,1024,8)]:
  z=build(hs,B,S,shift)
  if z: print(name,'unique',u,'SUCCESS',B,S,shift,z);return
