'wang':lambda x:(x^(x>>33))*0xff51afd7ed558ccd ^ ((x^(x>>33))*0xff51afd7ed558ccd>>33),
}
for n,f in funcs.items():show(n,f)
# search XOR shifts combinations
for cnt in range(20000):
 sh=random.sample(range(1,56),random.choice([2,3,4]))
 def f(x,sh=sh):
  for a in sh:x^=x>>a
  return x
 hs=[f(k)&0xffffffff for k in keys]
 z=build(hs)
 if z:
  print('FOUND xor',sh,'unique',len(set(hs)),z);break
else: print('no xor found')
# Search one multiply + folded source / shifts
for cnt in range(10000):
 c=random.randrange(1,1<<64)|1
 a=random.randrange(1,48)
 b=random.randrange(1,48)
 # mix likely: (x ^ x>>a)*c then >> b maybe
 hs=[(((k^(k>>a))*c)^( ((k^(k>>a))*c)>>b)) & 0xffffffff for k in keys]
 z=build(hs)
 if z:
  print('FOUND mult',hex(c),a,b,'unique',len(set(hs)),z);break
else:print('no mult found')
