edits.newText:
typedef struct {
    const char *next;
    unsigned id;
    int temperature;
} Decoded;

static inline Decoded decode_record(const char *p, const char *simd_limit) {
    uint64_t word;
    unsigned len = find_semicolon(p, simd_limit, &word);
    Decoded d;
    d.id = station_id(word, len);
    d.temperature = parse_temperature(p + len + 1, &d.next);
    return d;
}

static inline void update_stats(Stats *stats, Decoded d) {
    Stats *s = &stats[d.id];
    s->sum += d.temperature;
    s->count++;
    s->min = d.temperature < s->min ? d.temperature : s->min;
    s->max = d.temperature > s->max ? d.temperature : s->max;
}

static void *process(void *arg) {
    Worker *w = (Worker *)arg;
    const char *p = w->begin;
    while (p < w->end) {
        Decoded first = decode_record(p, w->simd_limit);
        p = first.next;
        if (p >= w->end) {
            update_stats(w->stats, first);
            break;
        }
        Decoded second = decode_record(p, w->simd_limit);
        p = second.next;
        update_stats(w->stats, first);
        update_stats(w->stats, second);
    }
    return NULL;
}

