static inline unsigned find_semicolon(const char *p, const char *simd_limit, uint64_t *word) {
    if (__builtin_expect(p <= simd_limit, 1)) {
        const __m128i semicolon = _mm_set1_epi8(';');
        const int mode = _SIDD_UBYTE_OPS | _SIDD_CMP_EQUAL_ANY | _SIDD_LEAST_SIGNIFICANT;
        __m128i block = _mm_loadu_si128((const __m128i *)p);
        *word = (uint64_t)_mm_cvtsi128_si64(block);
        int index = _mm_cmpistri(semicolon, block, mode);
        if (__builtin_expect(index != 16, 1)) return (unsigned)index;
        block = _mm_loadu_si128((const __m128i *)(p + 16));
        return 16u + (unsigned)_mm_cmpistri(semicolon, block, mode);
    }
    *word = first_word(p);
    const char *q = p;
    while (*q != ';') ++q;
    return (unsigned)(q - p);
}

