static inline unsigned station_id(uint64_t word, unsigned len, const char *name) {
    uint64_t key = word & prefix_masks[len < 6 ? len : 6];
    unsigned id = prefix_slots[(key * PREFIX_HASH_MULTIPLIER) >> 51];
    if (__builtin_expect(id == PREFIX_SENTINEL, 0)) {
        if (name[0] == 'A') return name[8] == 'a' ? 9 : 10;
        return name[7] == 'e' ? 325 : 326;
    }
    return id;
}

