edits.oldText:
static inline int parse_temperature(const char *p, const char **next) {
    unsigned neg = (unsigned)(p[0] == '-');
    p += neg;
    int first = p[0] - '0';
    unsigned one_digit = (unsigned)(p[1] == '.');
    int single = first * 10 + (p[2] - '0');
    int dual = first * 100 + (p[1] - '0') * 10 + (p[3] - '0');
    int choose_single = -(int)one_digit;
    int value = (single & choose_single) | (dual & ~choose_single);
    *next = p + 5 - one_digit;
    int sign = -(int)neg;
    return (value ^ sign) - sign;
}

edits.newText:
static inline int parse_temperature(const char *p, const char **next) {
    unsigned neg = (unsigned)(p[0] == '-');
    p += neg;
    uint16_t prefix;
    __builtin_memcpy(&prefix, p, sizeof(prefix));
    unsigned index = (prefix & 15u) | ((prefix >> 4) & 240u);
    unsigned spec = temperature_specs[index];
    unsigned one_digit = spec >> 10;
    unsigned value = (spec & 1023u) + ((unsigned char)p[3 - one_digit] & 15u);
    *next = p + 5 - one_digit;
    int sign = -(int)neg;
    return ((int)value ^ sign) - sign;
}

