static inline int parse_temperature(const char *p, const char **next) {
    unsigned neg = (unsigned)(p[0] == '-');
    p += neg;
    uint32_t raw;
    __builtin_memcpy(&raw, p, sizeof(raw));
    unsigned first = raw & 15u;
    unsigned one_digit = ((raw >> 8) & 255u) == '.';
    unsigned single = first * 10 + ((raw >> 16) & 15u);
    unsigned dual = first * 100 + ((raw >> 8) & 15u) * 10 + ((raw >> 24) & 15u);
    unsigned value = one_digit ? single : dual;
    *next = p + 5 - one_digit;
    int sign = -(int)neg;
    return ((int)value ^ sign) - sign;
}

